/// <summary>
/// Helper class for retrieving secrets from Azure Key Vault.
/// </summary>
public final class AVARUMKeyVaultHelper
{
}

Method.Source:
/// <summary>
/// Retrieves a secret value from Azure Key Vault based on the provided key name.
/// </summary>
/// <param name = "_keyValueKeyName">The name of the key in Key Vault.</param>
/// <returns>The secret value as a string.</returns>
public static str getKeyFromKeyVault(str _keyValueKeyName)
{     
    str value;

    if (strLen(_keyValueKeyName) == 0)
    {
        throw Global::error("@AVARUM:Error_KeyValueKeyNameIsEmpty");
    }
    try
    {
        KeyVaultCertificateTable certTable = KeyVaultCertificateTable::findByName(_keyValueKeyName);
        value = KeyVaultCertificateHelper::getManualSecretValue(certTable.RecId);
    }
    catch (Exception::CLRError)
    {
        throw Global::error(strFmt("@AVARUM:Error_KeyVaultNotConigured", _keyValueKeyName));
    }

    return value;
}
